from common import p,step,quantity,graph,svg,text,line
import math

def add_acids(b):
    code='R3.1'
    def mc(level,diff,title,stem,correct,distractors,reason,**kw):
        return b.add(code,level,diff,title,stem,correct=correct,distractors=distractors,reasoning=reason,**kw)
    def q(level,diff,title,stem,*parts,**kw):
        return b.add(code,level,diff,title,stem,parts=list(parts),**kw)
    mc('sl','easy','A proton accepted',r'In $\mathrm{NH_3(aq)+H_2O(l)\rightleftharpoons NH_4^+(aq)+OH^-(aq)}$, which species acts as the Brønsted–Lowry base in the forward reaction?',r'$\mathrm{NH_3}$',[r'$\mathrm{H_2O}$',r'$\mathrm{NH_4^+}$',r'$\mathrm{OH^-}$'],r'Ammonia accepts a proton from water to form $\mathrm{NH_4^+}$. A Brønsted–Lowry base is a proton acceptor.')
    mc('sl','easy','One-proton difference',r'What is the conjugate base of $\mathrm{H_2PO_4^-}$?',r'$\mathrm{HPO_4^{2-}}$',[r'$\mathrm{H_3PO_4}$',r'$\mathrm{PO_4^{3-}}$',r'$\mathrm{H_2PO_4^{2-}}$'],r'Removing one $\mathrm{H^+}$ removes one hydrogen and lowers the charge by one: $\mathrm{H_2PO_4^-\rightarrow H^++HPO_4^{2-}}$.')
    q('sl','medium','Two roles for hydrogencarbonate',r'The ion $\mathrm{HCO_3^-}$ can transfer a proton to water or accept a proton from water.',p('Write an equation showing each role.',step(r'As an acid: $\mathrm{HCO_3^-+H_2O\rightleftharpoons CO_3^{2-}+H_3O^+}$.'),step(r'As a base: $\mathrm{HCO_3^-+H_2O\rightleftharpoons H_2CO_3+OH^-}$.')),p('State the term for this behaviour and identify one conjugate pair in your equations.',step('The ion is amphiprotic.'),step(r'For example, $\mathrm{HCO_3^- / CO_3^{2-}}$ differ by one proton. Accept the other valid pairs.')))
    q('sl','easy','Hydrogen-ion concentration from pH',r'A solution has pH $3.42$ at $298\,\mathrm{K}$.',p(r'Calculate $[\mathrm{H^+}]$ in $\mathrm{mol\,dm^{-3}}$.',step(r'$[\mathrm{H^+}]=10^{-\mathrm{pH}}=10^{-3.42}$.','M1'),step(r'$[\mathrm{H^+}]=3.8\times10^{-4}\,\mathrm{mol\,dm^{-3}}$ (two significant figures).')),p('Explain why a decrease in pH by one unit would not mean a decrease in acidity.',step(r'It would increase $[\mathrm{H^+}]$ by a factor of ten, making the solution more acidic.')))
    q('sl','medium','Making a dilute acid standard',r'A student transfers $10.0\,\mathrm{cm^3}$ of $0.150\,\mathrm{mol\,dm^{-3}}$ hydrochloric acid into a $250.0\,\mathrm{cm^3}$ volumetric flask and makes the solution up to the mark. Assume complete ionization and negligible water contribution.',p('Calculate the final acid concentration and pH.',step(r'Moles transferred $=0.150\times0.0100=0.00150\,\mathrm{mol}$.','M1'),step(r'$[\mathrm{H^+}]=0.00150/0.2500=0.00600\,\mathrm{mol\,dm^{-3}}$.'),step(r'$\mathrm{pH}=-\log_{10}(0.00600)=2.222$.')),p('Identify an appropriate device for transferring the initial volume accurately.',step(r'A $10.0\,\mathrm{cm^3}$ volumetric pipette; a measuring cylinder is less precise.')))
    mc('sl','medium','Comparing acidic samples',r'Sample P has pH $2.6$ and sample Q has pH $4.1$. What is $[\mathrm{H^+}]_P/[\mathrm{H^+}]_Q$?',r'$31.6$',[r'$1.58$',r'$0.0316$',r'$10^{6.7}$'],r'The concentration ratio is $10^{-2.6}/10^{-4.1}=10^{1.5}=31.6$. A lower pH corresponds to more hydrogen ions.')
    q('sl','medium','Neutral water at another temperature',r'At a particular temperature, $K_\mathrm{w}=4.00\times10^{-14}\,\mathrm{mol^2\,dm^{-6}}$. Pure water at this temperature is neutral.',p(r'Calculate $[\mathrm{H^+}]$ and its pH.',step(r'Neutrality requires $[\mathrm{H^+}]=[\mathrm{OH^-}]$, so $[\mathrm{H^+}]^2=K_\mathrm{w}$.','M1'),step(r'$[\mathrm{H^+}]=2.00\times10^{-7}\,\mathrm{mol\,dm^{-3}}$ and pH $=6.699$.')),p('Explain why its pH being below 7 does not make this pure water acidic.',step(r'Acidity is determined by $[\mathrm{H^+}]>[\mathrm{OH^-}]$, not by a temperature-independent pH threshold. Here the concentrations are equal.')))
    q('sl','medium','A carbonate neutralized',r'Excess dilute hydrochloric acid is added to a sample of calcium carbonate.',p('Write a balanced equation including state symbols.',step(r'$\mathrm{CaCO_3(s)+2HCl(aq)\rightarrow CaCl_2(aq)+CO_2(g)+H_2O(l)}$; correct products.'),step('Correct coefficients and state symbols.')),p('Give an observable change and explain which product causes it.',step(r'Effervescence occurs because $\mathrm{CO_2}$ gas forms.')),p('Identify the parent acid and base that can form calcium chloride by neutralization.',step(r'Hydrochloric acid and calcium hydroxide (or calcium oxide).')))
    mc('sl','easy','Base or alkali',r'Which statement correctly distinguishes a base from an alkali?',r'An alkali is a water-soluble base; some bases are insoluble.',['Every base must contain a hydroxide ion in its formula.','A base must be stronger than an alkali.','Every base is a soluble metal hydroxide.'],r'An alkali is a soluble base. For example, ammonia is a base even though its formula contains no hydroxide ion; insoluble metal oxides can also behave as bases.')
    q('sl','medium','Strong is not concentrated',r'Bottle A contains $0.010\,\mathrm{mol\,dm^{-3}}$ hydrochloric acid. Bottle B contains $1.0\,\mathrm{mol\,dm^{-3}}$ ethanoic acid. A label describes A as a strong acid and B as a weak acid.',p('Explain why these descriptions are compatible with B having the greater acid concentration.',step('Strong/weak describes the extent of ionization in water.'),step('Concentration describes the amount of dissolved acid per volume; it is a different property.')),p('A student claims the labels alone prove that A has the lower pH. Evaluate the claim.',step(r'The claim is unsupported: pH depends on $[\mathrm{H^+}]$, which depends on both concentration and ionization.'),step('The hydrogen-ion concentrations or suitable equilibrium information would be needed to compare these unequal-concentration samples.')))
    q('sl','medium','Evidence for acid strength',r'Two monoprotic acids X and Y have equal analytical concentration and temperature. X conducts more strongly and reacts faster with identical cleaned magnesium strips. The solutions contain no other solutes.',p('Suggest which acid is stronger and explain both observations.',step(r'X is likely stronger because a larger fraction ionizes, producing more mobile ions.'),step(r'Its higher $[\mathrm{H^+}]$ also supports more frequent successful collisions with the magnesium surface.')),p('State why the temperature and magnesium surface must be controlled.',step('Temperature changes reaction rate and conductivity; surface area/condition changes the metal reaction rate. Matching them makes acid strength the relevant comparison.')),question_type='data-based')
    acidpts=[(0,1),(10,1.37),(20,1.95),(24,2.69),(24.9,3.70),(25,7),(25.1,10.30),(26,11.29),(30,11.96),(40,12.36),(50,12.52)]
    q('sl','medium','Reading a strong-acid titration',r'The graph shows $25.0\,\mathrm{cm^3}$ of a strong monoprotic acid titrated with $0.100\,\mathrm{mol\,dm^{-3}}$ sodium hydroxide at $298\,\mathrm{K}$.',p('Determine the equivalence volume and the original acid concentration.',step(r'The centre of the steep rise is at $25.0\,\mathrm{cm^3}$.','M1'),step(r'At equivalence $n(\mathrm{H^+})=n(\mathrm{OH^-})=0.100\times0.0250=0.00250\,\mathrm{mol}$.'),step(r'$c=0.00250/0.0250=0.100\,\mathrm{mol\,dm^{-3}}$.')),p('Explain the pH at equivalence.',step('It is 7 at 298 K because the strong acid and strong base neutralize in equal amounts, leaving a salt whose ions do not appreciably hydrolyse.')),diagram=graph('Strong acid with sodium hydroxide','NaOH added / cm³','pH',acidpts),question_type='data-based')
    q('sl','hard','Before the equivalence point',r'$20.0\,\mathrm{cm^3}$ of $0.0800\,\mathrm{mol\,dm^{-3}}$ HCl is mixed with $12.0\,\mathrm{cm^3}$ of $0.100\,\mathrm{mol\,dm^{-3}}$ NaOH. Volumes are additive and ionization is complete.',p('Calculate the pH of the mixture.',step(r'$n(\mathrm{H^+})=0.00160\,\mathrm{mol}$ and $n(\mathrm{OH^-})=0.00120\,\mathrm{mol}$.','M1'),step(r'Excess $\mathrm{H^+}=0.000400\,\mathrm{mol}$.'),step(r'$[\mathrm{H^+}]=0.000400/0.0320=0.0125\,\mathrm{mol\,dm^{-3}}$.','M1'),step(r'pH $=1.903$.')),p('Explain why the two initial pH values cannot simply be averaged.',step('Neutralization consumes ions and the final concentration uses the total volume; pH itself is logarithmic.')))
    q('sl','medium','Choosing how to measure pH',r'A coloured liquid is being monitored for a slow change from pH 5.2 to pH 5.5. A student can use universal indicator with a colour chart or a calibrated pH probe.',p('Choose the more suitable method and justify your choice.',step('Use the calibrated pH probe.'),step('It resolves the small numerical change more precisely and is not confused by the sample colour.')),p('State one calibration or measurement practice that improves the result.',step('Accept calibration with appropriate standard buffers, rinsing between samples, maintaining temperature, or waiting for the reading to stabilize.')),question_type='data-based')
    q('sl','medium','An unknown monoprotic acid',r'Three concordant titrations of $20.00\,\mathrm{cm^3}$ portions of an unknown monoprotic acid use $16.42$, $16.38$ and $16.40\,\mathrm{cm^3}$ of $0.1250\,\mathrm{mol\,dm^{-3}}$ NaOH. Assume the end point is a valid measure of equivalence.',p('Calculate the acid concentration using the mean titre.',step(r'Mean titre $=16.40\,\mathrm{cm^3}$.','M1'),step(r'$n(\text{acid})=n(\mathrm{NaOH})=0.1250\times0.01640=0.002050\,\mathrm{mol}$.','M1'),step(r'$c=0.002050/0.02000=0.1025\,\mathrm{mol\,dm^{-3}}$.')),p('Explain whether this result alone determines if the acid is strong or weak.',step('No. Titration measures the total amount that reacts stoichiometrically, not the fraction ionized before titration.')),question_type='data-based')
    mc('ahl','easy','Using pOH',r'A solution at $298\,\mathrm{K}$ has $[\mathrm{OH^-}]=2.5\times10^{-3}\,\mathrm{mol\,dm^{-3}}$. Take $K_\mathrm{w}=1.0\times10^{-14}\,\mathrm{mol^2\,dm^{-6}}$. What is its pH?',r'$11.40$',[r'$2.60$',r'$3.60$',r'$12.60$'],r'pOH $=-\log_{10}(2.5\times10^{-3})=2.60$. At 298 K, pH $=14.00-2.60=11.40$.')
    mc('ahl','medium','Ordering weak acids',r'Three acids have $\mathrm{p}K_\mathrm{a}$ values $3.2$, $4.9$ and $6.1$. Which ordering is strongest to weakest?',r'$3.2,\ 4.9,\ 6.1$',[r'$6.1,\ 4.9,\ 3.2$',r'$4.9,\ 3.2,\ 6.1$','Their relative strengths cannot be inferred.'],r'Smaller $\mathrm{p}K_\mathrm{a}$ means larger $K_\mathrm{a}$ and a greater tendency to donate a proton.')
    q('ahl','medium','Weak-acid approximation',r'A monoprotic acid HA has $K_\mathrm{a}=1.60\times10^{-5}\,\mathrm{mol\,dm^{-3}}$. Its analytical concentration is $0.100\,\mathrm{mol\,dm^{-3}}$. Neglect water ionization.',p('Calculate the pH using the small-dissociation approximation.',step(r'$K_\mathrm{a}=[\mathrm{H^+}][\mathrm{A^-}]/[\mathrm{HA}]\approx x^2/0.100$.','M1'),step(r'$x=\sqrt{1.60\times10^{-5}\times0.100}=1.265\times10^{-3}\,\mathrm{mol\,dm^{-3}}$.'),step(r'pH $=2.90$.')),p('Check whether the approximation is reasonable.',step(r'The fraction dissociated is $0.001265/0.100=0.01265$, about $1.27\%$; replacing the equilibrium acid concentration by its initial value introduces only a small change.')))
    q('ahl','medium','A weak base in water',r'A base B obeys $\mathrm{B+H_2O\rightleftharpoons BH^++OH^-}$, with $K_\mathrm{b}=4.0\times10^{-6}\,\mathrm{mol\,dm^{-3}}$. Its concentration is $0.025\,\mathrm{mol\,dm^{-3}}$ at $298\,\mathrm{K}$; use $K_\mathrm{w}=1.0\times10^{-14}$ and the small-ionization approximation.',p('Calculate the pH.',step(r'$[\mathrm{OH^-}]\approx\sqrt{K_\mathrm{b}c}=\sqrt{4.0\times10^{-6}\times0.025}=3.16\times10^{-4}\,\mathrm{mol\,dm^{-3}}$.','M1'),step(r'pOH $=3.50$.'),step(r'pH $=14.00-3.50=10.50$.')),p('Write the expression for the conjugate acid dissociation and calculate its constant.',step(r'$\mathrm{BH^++H_2O\rightleftharpoons B+H_3O^+}$.'),step(r'$K_\mathrm{a}=K_\mathrm{w}/K_\mathrm{b}=2.5\times10^{-9}\,\mathrm{mol\,dm^{-3}}$.')))
    mc('ahl','medium','Conjugate strengths',r'At a fixed temperature, acid HA has a larger $K_\mathrm{a}$ than acid HB. What follows for their conjugate bases?',r'$\mathrm{A^-}$ has the smaller $K_\mathrm{b}$.',[r'$\mathrm{A^-}$ has the larger $K_\mathrm{b}$.','Both conjugate bases must be strong.','The two conjugate bases must have equal strength.'],r'For each conjugate pair, $K_\mathrm{a}K_\mathrm{b}=K_\mathrm{w}$. At the same temperature the larger acid constant therefore gives the smaller base constant.')
    q('ahl','medium','Why salt solutions differ',r'Consider separate dilute aqueous solutions of sodium ethanoate and ammonium chloride at $298\,\mathrm{K}$.',p('Write the hydrolysis equation for the ion that changes pH in each solution.',step(r'$\mathrm{CH_3COO^-+H_2O\rightleftharpoons CH_3COOH+OH^-}$.'),step(r'$\mathrm{NH_4^++H_2O\rightleftharpoons NH_3+H_3O^+}$.')),p('Predict whether each solution is acidic or alkaline and explain the role of the remaining ion.',step('Sodium ethanoate is alkaline; ammonium chloride is acidic.'),step(r'$\mathrm{Na^+}$ and $\mathrm{Cl^-}$ do not appreciably alter pH under these conditions.')))
    weakpts=[(0,2.88),(5,4.14),(10,4.57),(12.5,4.74),(20,5.34),(24,6.12),(24.9,7.14),(25,8.72),(25.1,10.30),(26,11.29),(30,11.96),(40,12.36)]
    q('ahl','medium','Features of a weak-acid curve',r'The graph represents a weak monoprotic acid titrated with a strong base at $298\,\mathrm{K}$.',p('Identify the equivalence volume and estimate the acid pKa.',step(r'Equivalence occurs at about $25.0\,\mathrm{cm^3}$.','M1'),step(r'At half equivalence, $12.5\,\mathrm{cm^3}$, pH is about $4.7$, so pKa is about $4.7$. Accept a graph-reading estimate from $4.6$ to $4.9$.')),p('Explain why the equivalence-point pH is greater than 7.',step('At equivalence the solution contains the conjugate base of the weak acid.'),step(r'It reacts with water to produce hydroxide ions: $\mathrm{A^-+H_2O\rightleftharpoons HA+OH^-}$.')),diagram=graph('Weak acid titrated with strong base','Base added / cm³','pH',weakpts),question_type='data-based')
    q('ahl','medium','Finding Ka from a partial titration',r'A weak monoprotic acid has an equivalence volume of $30.0\,\mathrm{cm^3}$ when titrated with NaOH. After $15.0\,\mathrm{cm^3}$ has been added, the measured pH is $4.36$.',p('Determine Ka and explain the link between the measured pH and pKa.',step(r'At half equivalence the amounts of HA and $\mathrm{A^-}$ are equal.'),step(r'$K_\mathrm{a}=[\mathrm{H^+}][\mathrm{A^-}]/[\mathrm{HA}]=[\mathrm{H^+}]$, so pKa $=4.36$.','M1'),step(r'$K_\mathrm{a}=10^{-4.36}=4.4\times10^{-5}\,\mathrm{mol\,dm^{-3}}$.')),question_type='data-based')
    q('ahl','medium','Choosing an indicator from evidence',r'A weak acid–strong base titration has its steep pH rise between pH $7.5$ and $10.5$. Available indicators change colour over: P, $3.1$–$4.4$; Q, $6.0$–$7.0$; R, $8.2$–$10.0$.',p('Select an indicator and explain using the supplied data.',step('Choose R.'),step('Its colour-change range lies within the steep rise, so a small volume change produces the end point close to equivalence.')),p('Distinguish the end point from the equivalence point.',step('The end point is the observed indicator colour change.'),step('The equivalence point is where acid and base have reacted in the stoichiometric amounts.')),question_type='data-based')
    q('ahl','medium','An indicator as an equilibrium',r'Indicator HInd is red; its conjugate base $\mathrm{Ind^-}$ is yellow. The indicator has $K_\mathrm{a}=1.0\times10^{-5}\,\mathrm{mol\,dm^{-3}}$.',p('Write its dissociation equilibrium and explain its colour at pH 3.',step(r'$\mathrm{HInd\rightleftharpoons H^++Ind^-}$.'),step(r'High $[\mathrm{H^+}]$ shifts the equilibrium towards HInd, so red predominates.')),p(r'Calculate $[\mathrm{Ind^-}]/[\mathrm{HInd}]$ at pH 6.',step(r'$[\mathrm{Ind^-}]/[\mathrm{HInd}]=K_\mathrm{a}/[\mathrm{H^+}]=10^{-5}/10^{-6}=10$.','M1'),step('The yellow form is ten times as concentrated as the red form.')))
    q('ahl','medium','How an acidic buffer works',r'A buffer contains ethanoic acid and sodium ethanoate.',p('Write equations showing how the buffer reacts with small additions of strong acid and strong alkali.',step(r'Added acid: $\mathrm{CH_3COO^-+H^+\rightarrow CH_3COOH}$.'),step(r'Added alkali: $\mathrm{CH_3COOH+OH^-\rightarrow CH_3COO^-+H_2O}$.')),p('Explain why the buffer cannot hold its pH unchanged after an arbitrarily large addition of acid.',step('The ethanoate component has a finite amount.'),step('Once much of it is consumed, the ratio of conjugate components changes greatly; after exhaustion, excess added acid controls the pH.')))
    q('ahl','medium','pH from a buffer ratio',r'A buffer contains $0.060\,\mathrm{mol}$ HA and $0.090\,\mathrm{mol}$ of its conjugate base in the same solution. For HA, $K_\mathrm{a}=2.0\times10^{-5}\,\mathrm{mol\,dm^{-3}}$.',p('Calculate the buffer pH using the acid equilibrium expression.',step(r'$[\mathrm{H^+}]=K_\mathrm{a}[\mathrm{HA}]/[\mathrm{A^-}]$.','M1'),step(r'The shared volume cancels: $[\mathrm{H^+}]=2.0\times10^{-5}\times0.060/0.090=1.33\times10^{-5}\,\mathrm{mol\,dm^{-3}}$.'),step(r'pH $=4.88$.')),p('State one assumption in this calculation.',step('The stated acid and conjugate-base amounts are sufficiently large that their small equilibrium changes can be neglected.')))
    q('ahl','hard','Buffer after adding strong acid',r'A buffer initially contains $0.0400\,\mathrm{mol}$ HA and $0.0500\,\mathrm{mol}$ $\mathrm{A^-}$. Then $0.0100\,\mathrm{mol}$ HCl is added. The acid has $K_\mathrm{a}=1.80\times10^{-5}\,\mathrm{mol\,dm^{-3}}$. Assume complete reaction of added strong acid before calculating the equilibrium pH.',p('Determine the amounts of both buffer components after the addition.',step(r'$\mathrm{A^-+H^+\rightarrow HA}$ consumes $0.0100\,\mathrm{mol}$ $\mathrm{A^-}$.','M1'),step(r'$n(\mathrm{HA})=0.0500\,\mathrm{mol}$ and $n(\mathrm{A^-})=0.0400\,\mathrm{mol}$.')),p('Calculate the new pH.',step(r'$[\mathrm{H^+}]=1.80\times10^{-5}\times0.0500/0.0400=2.25\times10^{-5}\,\mathrm{mol\,dm^{-3}}$.','M1'),step(r'pH $=4.648$.')))
    q('ahl','hard','Dilution and buffer capacity',r'A buffer is diluted from $100\,\mathrm{cm^3}$ to $1.00\,\mathrm{dm^3}$. Before and after dilution, compare equal $50\,\mathrm{cm^3}$ samples. Assume the buffer approximation remains valid.',p('Predict the immediate change in buffer pH, and explain.',step('The pH remains approximately the same.'),step('Both component concentrations decrease by the same factor, so their ratio, and hence the equilibrium hydrogen-ion concentration under the approximation, stays approximately constant.')),p('Compare the resistance of the two equal-volume samples to an identical small addition of strong acid.',step('The diluted sample resists the addition less effectively.'),step('Its equal-volume portion contains one tenth as many moles of each buffer component; the same added acid therefore causes a larger fractional change in their ratio.')))
    q('ahl','hard','Preparing a target buffer',r'A solution contains $0.100\,\mathrm{mol}$ of a weak monoprotic acid HA with pKa $=4.50$. A student adds solid NaOH to make a buffer of pH $4.50$, assuming negligible volume change and complete neutralization by the added NaOH. Use $M(\mathrm{NaOH})=40.00\,\mathrm{g\,mol^{-1}}$.',p('Calculate the amount and mass of NaOH required.',step(r'At pH $=$ pKa, $[\mathrm{A^-}]=[\mathrm{HA}]$.','M1'),step(r'If $x$ mol NaOH reacts, $x=0.100-x$, so $x=0.0500\,\mathrm{mol}$.'),step(r'Mass $=0.0500\times40.00=2.00\,\mathrm{g}$.')),p('Explain why adding 0.100 mol NaOH would not give the requested buffer.',step('That would neutralize essentially all the weak acid, leaving primarily its conjugate base rather than appreciable amounts of both buffer partners.')))
    assert len(b.questions)==30
